class AniListForecastPage extends StatefulWidget {
  final Watchlist watchlist;
  const AniListForecastPage({Key? key, required this.watchlist}) : super(key: key);

  @override
  State<AniListForecastPage> createState() => _AniListForecastPageState();
}

class _AniListForecastPageState extends State<AniListForecastPage> {
  final AniListService _service = AniListService();
  bool _loading = true;
  Map<DateTime, List<Map<String, dynamic>>> _forecast = {};

  @override
  void initState() {
    super.initState();
    _buildForecast();
  }

  Future<void> _buildForecast() async {
    final now = DateTime.now();
    final since = now.subtract(const Duration(days: 7));
    final until = now.add(const Duration(days: 7));

    final Map<DateTime, List<Map<String, dynamic>>> tmp = {};

    for (final entry in widget.watchlist.entries) {
      final added = entry.addedAt;
      if (added == null) continue;
      if (added.isBefore(since)) continue; // only anime added in last 7 days

      final media = await _service.getNextAiringForTitle(entry.title);
      if (media == null) continue;
      final next = media['nextAiringEpisode'] as Map<String, dynamic>?;
      if (next == null) continue;
      final airingAt = next['airingAt'] as int?; // unix timestamp
      if (airingAt == null) continue;
      final dt = DateTime.fromMillisecondsSinceEpoch(airingAt * 1000);
      if (dt.isBefore(now) || dt.isAfter(until)) continue;

      final day = DateTime(dt.year, dt.month, dt.day);
      tmp.putIfAbsent(day, () => []).add({
        'title': media['title']?['userPreferred'] ?? entry.title,
        'episode': next['episode'],
        'airingAt': dt,
      });
    }

    if (mounted) setState(() { _forecast = tmp; _loading = false; });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('AniList Prognose')),
      body: _loading
        ? const Center(child: CircularProgressIndicator())
        : _forecast.isEmpty
            ? const Center(child: Text('Keine vorhergesagten Episoden in den nächsten 7 Tagen'))
            : ListView(
                children: _forecast.keys.toList()..sort((a,b)=>a.compareTo(b))).map((day) {
                  final items = _forecast[day]!;
                  return Card(
                    margin: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
                    child: Padding(
                      padding: const EdgeInsets.all(12.0),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text('${day.day.toString().padLeft(2,'0')}.${day.month.toString().padLeft(2,'0')}.${day.year}', style: Theme.of(context).textTheme.titleMedium),
                          const SizedBox(height: 8),
                          ...items.map((it) => ListTile(
                            title: Text('${it['title']} — Ep ${it['episode']}'),
                            subtitle: Text('${it['airingAt']}'),
                          )),
                        ],
                      ),
                    ),
                  );
                }.toList(),
      );
  }
}
